        if path == "/graph/path/all":
            return _handle_graph_path_all(method, environ, start_response)

        if path == "/graph/path":
            return _handle_graph_path(method, environ, start_response)

        if path == "/promotion/blockers":
            return _handle_promotion_blockers(method, environ, start_response)

        if path == "/lifecycle":
            # Global lifecycle summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_lifecycle_summary(method, environ, start_response)

        if path == "/dependency-vulnerability-impact":
            # Global dependency vulnerability impact summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_global_dependency_vulnerability_impact(
                method, environ, start_response
            )

        if path == "/upload-sessions":
            # Global chunk upload session summary; the handler answers the
            # 405 (Allow: GET) for every other method.
            return _handle_upload_sessions(method, environ, start_response)

        if path == "/vulnerability-exceptions":
            # Global exemption summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_global_vulnerability_exceptions(
                method, environ, start_response
            )

        if path == "/sboms":
            # Global SBOM summary; the handler answers the 405 (Allow: GET)
            # for every other method.
            return _handle_sboms_summary(method, environ, start_response)

        if path == "/licenses":
            # Global license summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_licenses_summary(method, environ, start_response)

        if path == "/provenance":
            # Global build provenance summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_provenance_summary(method, environ, start_response)

        if path == "/signatures":
            # Global content signature summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_signatures_summary(method, environ, start_response)

        if path == "/risk":
            # Global risk summary; the handler answers the 405 (Allow: GET)
