                start_response,
                "405 Method Not Allowed",
                "method_not_allowed",
                f"Method {method} is not allowed for this path.",
                allowed="GET, POST",
            )

        if path == "/policies":
            return _handle_default_policy(method, environ, start_response)

        if path == "/cache":
